{
  "title": "The Gilded Gauntlet",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The party arrives at the ruined city gates.",
      "visual_description": "Massive iron gates, twisted and rusted, stand half-open before a crumbling wall. Faded royal banners hang limply from the battlements. The sky is gray and heavy.",
      "characters": ["Kaelen", "Mira", "Thorne"]
    },
    {
      "scene_number": 2,
      "caption": "Frightened townspeople warn them of danger.",
      "visual_description": "A cluster of ragged citizens huddle in a shadowy alley, pointing toward the inner city. One old woman clutches a child; a man gestures frantically.",
      "characters": ["Kaelen", "Mira", "Thorne", "Elara", "Old Woman", "Townsperson"]
    },
    {
      "scene_number": 3,
      "caption": "Armored patrols march through the main square.",
      "visual_description": "A column of black-armored soldiers moves in unison across a cracked plaza, their shields bearing a serpent crest. Dust swirls at their boots.",
      "characters": ["Patrol Captain", "Soldier 1", "Soldier 2", "Soldier 3"]
    },
    {
      "scene_number": 4,
      "caption": "The team scouts a cursed tower.",
      "visual_description": "A slender spire leans precariously, its stones weeping a phosphorescent green slime. Windows glow with an unnatural amber light.",
      "characters": ["Kaelen", "Mira", "Thorne"]
    },
    {
      "scene_number": 5,
      "caption": "Rumors of a dragon reach their ears.",
      "visual_description": "In a smoky tavern, a one-eyed barkeep leans forward, whispering. A map on the table shows a crude dragon symbol near the palace.",
      "characters": ["Kaelen", "Mira", "Thorne", "Barkeep", "Patron"]
    },
    {
      "scene_number": 6,
      "caption": "They encounter a magic door that speaks.",
      "visual_description": "A massive oak door set in a stone archway, carved with runes that pulse with blue light. The door's face, formed in the wood grain, regards them with glowing eyes.",
      "characters": ["Kaelen", "Mira", "Thorne", "Magic Door"]
    },
    {
      "scene_number": 7,
      "caption": "The magic door presents a riddle.",
      "visual_description": "Runes on the door rearrange into a poetic riddle. Mira steps forward, reading aloud. Thorne tightens his grip on his sword.",
      "characters": ["Kaelen", "Mira", "Thorne", "Magic Door"]
    },
    {
      "scene_number": 8,
      "caption": "Mira solves the riddle and the door opens.",
      "visual_description": "The runes flash brightly, then fade. The door swings inward with a grinding groan, revealing a dark hallway lined with torches.",
      "characters": ["Kaelen", "Mira", "Thorne", "Magic Door"]
    },
    {
      "scene_number": 9,
      "caption": "They descend into a crypt beneath the tower.",
      "visual_description": "A spiral staircase descends into damp gloom. Cobwebs cling to skulls set in niches. Faint whispers echo from below.",
      "characters": ["Kaelen", "Mira", "Thorne"]
    },
    {
      "scene_number": 10,
      "caption": "A trap is triggered — floor spikes rise.",
      "visual_description": "As Thorne steps on a loose flagstone, metal spikes erupt from the floor. Kaelen grabs his arm and pulls him back just in time.",
      "characters": ["Kaelen", "Mira", "Thorne"]
    },
    {
      "scene_number": 11,
      "caption": "They find the captive in a jeweled cage.",
      "visual_description": "In a chamber lit by a crystal chandelier, a gilded cage hangs from the ceiling. Inside, a young woman with silver hair clutches the bars.",
      "characters": ["Kaelen", "Mira", "Thorne", "Lyra"]
    },
    {
      "scene_number": 12,
      "caption": "Patrol guards ambush them in the chamber.",
      "visual_description": "The chamber doors burst open and four armored soldiers rush in, swords drawn. Mira throws a flash bomb, filling the room with blinding light.",
      "characters": ["Kaelen", "Mira", "Thorne", "Lyra", "Soldier 1", "Soldier 2", "Soldier 3", "Soldier 4"]
    },
    {
      "scene_number": 13,
      "caption": "The party fights through the guards.",
      "visual_description": "Thorne engages two soldiers with broad sweeps of his blade. Kaelen uses a conjured shield to deflect arrows. Mira picks the cage lock with nimble fingers.",
      "characters": ["Kaelen", "Mira", "Thorne", "Lyra", "Soldier 1", "Soldier 2", "Soldier 3", "Soldier 4"]
    },
    {
      "scene_number": 14,
      "caption": "Lyra joins the party with a hidden dagger.",
      "visual_description": "Freed from the cage, Lyra draws a slender dagger from her boot and helps dispatch the last soldier. She nods at the others, ready.",
      "characters": ["Kaelen", "Mira", "Thorne", "Lyra"]
    },
    {
      "scene_number": 15,
      "caption": "They race through the palace corridors.",
      "visual_description": "Torchlit hallways lined with tattered tapestries. The party runs as patrol horns blare behind them. A chandelier crashes, blocking their pursuers.",
      "characters": ["Kaelen", "Mira", "Thorne", "Lyra"]
    },
    {
      "scene_number": 16,
      "caption": "The dragon appears atop the palace roof.",
      "visual_description": "A sleek, crimson dragon lands on the palace dome, scales gleaming. It roars, sending a wave of heat across the courtyard. Banners catch fire.",
      "characters": ["Kaelen", "Mira", "Thorne", "Lyra", "Crimson Dragon"]
    },
    {
      "scene_number": 17,
      "caption": "They dash across the crumbling bridge.",
      "visual_description": "A narrow stone bridge spans a chasm, its arches cracked and missing stones. The party runs, dodging falling masonry as the dragon swoops overhead.",
      "characters": ["Kaelen", "Mira", "Thorne", "Lyra", "Crimson Dragon"]
    },
    {
      "scene_number": 18,
      "caption": "The bridge collapses behind them; they escape.",
      "visual_description": "The bridge crumbles into the gorge as Kaelen makes the final leap to safety. The dragon circles and retreats. The ruined city fades into the mist.",
      "characters": ["Kaelen", "Mira", "Thorne", "Lyra"]
    }
  ]
}

